"""Run from the repo root:  python install_storefront.py
Writes the new storefront into frontend/ and backend/app/static/ (overwrites index.html + storefront.css)."""
import base64, zlib, os, sys
FILES = {
    "index.html": "",
    "storefront.css": "",
}
TARGETS = ["frontend", os.path.join("backend", "app", "static")]
ok = False
for t in TARGETS:
    if not os.path.isdir(t):
        print("skip (folder not found):", t); continue
    for name, data in FILES.items():
        with open(os.path.join(t, name), "wb") as f:
            f.write(zlib.decompress(base64.b64decode(data)))
        print("written:", os.path.join(t, name)); ok = True
if not ok:
    sys.exit("Run this from the repo root (the folder that contains 'frontend' and 'backend').")
print("Done. Hard-refresh the browser (Ctrl+Shift+R).")
